#include "learned_motion_model.h"
#include <math.h>
#include <string.h>
static unsigned idx(motion_vec2_t d,float m){float a=atan2f(d.y,d.x);if(a<0)a+=6.2831853f;return((unsigned)(a*360/6.2831853f)%360)*4+(unsigned)(motion_clampf(m,0,.9999f)*4);}void learned_motion_model_reset(learned_motion_model_t*m){memset(m,0,sizeof(*m));m->version=1;}void learned_motion_model_observe(learned_motion_model_t*m,const motion_state2_t*s){float mag=hypotf(s->position.x,s->position.y),v=hypotf(s->velocity.x,s->velocity.y),a=hypotf(s->acceleration.x,s->acceleration.y),j=hypotf(s->jerk.x,s->jerk.y);learned_motion_cell_t*c=&m->cell[idx(s->position,mag)];c->v_sum+=v;c->a_sum+=a;c->j_sum+=j;if(v>c->v_peak)c->v_peak=v;if(a>c->a_peak)c->a_peak=a;if(j>c->j_peak)c->j_peak=j;c->samples++;m->total_samples++;}motion_limits_t learned_motion_model_query(const learned_motion_model_t*m,motion_vec2_t d,float a){motion_limits_t r={1,4,20,.05f,1,.2f};if(m){const learned_motion_cell_t*c=&m->cell[idx(d,a)];if(c->samples){r.velocity_max=c->v_peak;r.acceleration_max=c->a_peak;r.jerk_max=c->j_peak;}}return r;}
